    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # Each line through the rectangle extends toward the side opposite any
    # isolated marker on that line; without markers, it extends both ways.
    for r in range(r0, r1 + 1):
        left_mark = any(grid[r][c] not in (0, 2) for c in range(c0))
        right_mark = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if right_mark or not left_mark:
            for c in range(c0):
                if grid[r][c] == 0: out[r][c] = 2
        if left_mark or not right_mark:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0: out[r][c] = 2
    for c in range(c0, c1 + 1):
