        down_mark = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if down_mark or not up_mark:
            for r in range(r0):
                if grid[r][c] == 0: out[r][c] = 2
        if up_mark or not down_mark:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0: out[r][c] = 2
    return out

